scwin.fn_GetPar, scwin.fn_SetPar = "";
scwin.gDepCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


//기준일자 지정검색 
scwin.fn_list_sync = function() {
    if ($c.stf.getObjectValue(edt_BASE_DD) > $c.ut.cGetToday("yyyymmdd")) {
        $c.win.alert("기준일이 현재일보다 큽니다.");
        edt_BASE_DD.focus();
        return;
    }
    if (!$c.lc.fn_TrHoldyYn(dts_CHECK, $c.stf.getObjectValue(edt_BASE_DD))) {
        return;
    }
    var vMarketTpCd = "";
    if (js_market == "1") {
        vMarketTpCd = 'STK';
    } else if (js_market == "2") {
        vMarketTpCd = 'KSQ';
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_mkt);
    }
    var gCommonIsu = 'N';
    if (chk_common_isu.checked) {
        gCommonIsu = 'Y';
    }
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LISTISUDTLSRCH_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstsrch.listisudtlsrch_basedt.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param02=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param03=" + vMarketTpCd + "&{P}param04=" + $c.stf.getObjectValue(cmb_DEP_CD) + "&{P}param05=" + $c.stf.getObjectValue(cmb_DEP_CD) + "&{P}param06=" + $c.stf.getObjectValue(cmb_EMP_NO) + "&{P}param07=" + $c.stf.getObjectValue(cmb_EMP_NO) + "&{P}param08=" + gCommonIsu + "&{P}param09=" + gCommonIsu;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List); // 그리드명을 표기		

};


//콤보
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List); //데이터 로딩중닫기 및 조회없음 처리		

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.img_BASE_DD_onclick = function() {
    popUpCalendar2(edt_BASE_DD);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_DEP_CD, "VALUE", cmb_DEP_CD.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd || dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_small_ind_OnFilter = function(row) {
    //  중분류에 해당하는 소분류를 보여준다.
    if (gInd == "%") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        var s_ind = dts_small_ind.getCellData(row, "VALUE");
        //alert(s_ind);
        if (s_ind.substring(0, 4) == gInd || dts_small_ind.getCellData(row, "VALUE") == "%") {
            return true;
        } else {
            return false;
        }
    }
};
