        $c.cm.setColumnProp(grd_List, "PUBOFR_FINAL_PRC", "Show", "false");
        $c.cm.setColumnProp(grd_List, "PUBOFR_SHRS", "Show", "false");
        $c.cm.setColumnProp(grd_List, "PUBOFR_FINAL_AMT", "Show", "false");
    }
};
scwin.img_Search_onclick = function() {
    if ($c.stf.getObjectValue(edt_BASE_DD) != "") {
        scwin.fn_list_sync();
    } else {
        $c.win.alert("기준일자를 입력하세요");
    }
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //grd_List.GridToExcel("상장종목조검검색 목록", "", 1); //show false인것은 안보여준다.(type = 1)
        $c.data.downloadGridViewOffice(grd_List, "상장종목조검검색 목록", "", 8, 0);
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    edt_BASE_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    if (js_market == "1" || js_market == "2") {
        $c.cm.setColumnProp(grd_List, "MKT_ID", "Show", false);
        $c.stf.showObj(panel_rdo_mkt, false);
        $c.stf.showObj(panel_chk_mkt_id, false);
    } else {
        $c.cm.setColumnProp(grd_List, "MKT_ID", "Show", true);
        $c.stf.showObj(panel_rdo_mkt, true);
        $c.stf.showObj(panel_chk_mkt_id, true);
    }

    //round처리
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_SetCode();

    //초기로딩시 3개 칼럼만 표시한다.

};
